class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        ts = set(targetIndices); m = len(pattern)
        dp = [-10**9] * (m + 1); dp[0] = 0
        for i, ch in enumerate(source):
            for j in range(min(i, m - 1), -1, -1):
                if ch == pattern[j]:
                    dp[j + 1] = max(dp[j + 1], dp[j] + (1 if i in ts else 0))
        return dp[m]

