        unordered_set<int> ts(targetIndices.begin(), targetIndices.end());
        int m = pattern.size();
        vector<int> dp(m + 1, INT_MIN / 2); dp[0] = 0;
        for (int i = 0; i < (int)source.size(); i++)
            for (int j = min(i, m - 1); j >= 0; j--)
                if (source[i] == pattern[j])
                    dp[j + 1] = max(dp[j + 1], dp[j] + (ts.count(i) ? 1 : 0));
        return dp[m];
    }
};

