        INF = float('inf')
        e = [INF] * (m + 1); e[0] = -1
        j = 0
        for i, ch in enumerate(source):
            if j < m and ch == pattern[j]: e[j + 1] = i; j += 1
        l = [-INF] * (m + 1); l[m] = n
        j = m - 1
        for i in range(n - 1, -1, -1):
            if j >= 0 and source[i] == pattern[j]: l[j] = i; j -= 1
        pos = {}
        for j, ch in enumerate(pattern): pos.setdefault(ch, []).append(j)
        ans = 0
        for i in targetIndices:
            for j in pos.get(source[i], ()):
                if e[j] < i and l[j + 1] > i:
                    ans += 1; break
        return ans

