class Solution {
public:
    int maxRemovals(string source, string pattern, vector<int>& targetIndices) {
        int n = source.size(), m = pattern.size();
        const int INF = INT_MAX;
        vector<int> e(m + 1, INF), l(m + 1, -INF);
        e[0] = -1; l[m] = n;
        for (int i = 0, j = 0; i < n; i++)
            if (j < m && source[i] == pattern[j]) { e[++j] = i; }
        for (int i = n - 1, j = m - 1; i >= 0; i--)
            if (j >= 0 && source[i] == pattern[j]) { l[j--] = i; }
        vector<vector<int>> pos(26);
        for (int j = 0; j < m; j++) pos[pattern[j] - 'a'].push_back(j);
        int ans = 0;
        for (int i : targetIndices)
            for (int j : pos[source[i] - 'a'])
                if (e[j] < i && l[j + 1] > i) { ans++; break; }
        return ans;
    }
};

