class Solution {
    public int maxRemovals(String source, String pattern, List<Integer> targetIndices) {
        int n = source.length(), m = pattern.length();
        int[] e = new int[m + 1], l = new int[m + 1];
        Arrays.fill(e, Integer.MAX_VALUE); Arrays.fill(l, Integer.MIN_VALUE);
        e[0] = -1; l[m] = n;
        for (int i = 0, j = 0; i < n; i++)
            if (j < m && source.charAt(i) == pattern.charAt(j)) e[++j] = i;
        for (int i = n - 1, j = m - 1; i >= 0; i--)
            if (j >= 0 && source.charAt(i) == pattern.charAt(j)) l[j--] = i;
        List<List<Integer>> pos = new ArrayList<>();
        for (int c = 0; c < 26; c++) pos.add(new ArrayList<>());
        for (int j = 0; j < m; j++) pos.get(pattern.charAt(j) - 'a').add(j);
        int ans = 0;
        for (int i : targetIndices)
            for (int j : pos.get(source.charAt(i) - 'a'))
                if (e[j] < i && l[j + 1] > i) { ans++; break; }
        return ans;
    }
}

